```sparql
PREFIX dbo: <http://dbpedia.org/ontology/> PREFIX res: <http://dbpedia.org/resource/> SELECT ?timeZone WHERE { res:Salt_Lake_City dbo:timeZone ?timeZone }
```

```sparql
PREFIX dbo: <http://dbpedia.org/ontology/> PREFIX res: <http://dbpedia.org/resource/> SELECT ?mountain WHERE { res:Germany dbo:highest ?mountain . ?mountain rdf:type dbo:Mountain }
```

```sparql
PREFIX dbo: <http://dbpedia.org/ontology/> PREFIX res: <http://dbpedia.org/resource/> SELECT DISTINCT ?artist WHERE { ?artist dbo:birthDate ?date . res:Rachel_Stevens dbo:birthDate ?date }
```

